import { RowTools, Card } from "march/ui"

// dondurma sıralaman: tatları oklarla yukarı / aşağı taşı; birinci altın renginde ve büyük yazılır
export function FlavorRanking() {
  let $list = ["Fıstıklı", "Vişneli", "Limonlu", "Karamelli"]
  const move = (i: number, d: number) => { const n = [...$list]; [n[i], n[i + d]] = [n[i + d]!, n[i]!]; $list = n }
  return <Card m:theme="night" title="Dondurma sıralaman">
    <ol sx={{ flex: "col", gap: 2 }}>
      {$list.map((name, i) => <li sx={{ flex: ["row", "between", "center"], gap: 2 }}>
        <span sx={{ text: i === 0 ? "xl" : "md", color: i === 0 ? "brand-gold" : "muted" }}>{i + 1}. {name}</span>
        <RowTools actions={["up", "down"]} index={i} count={$list.length} size="sm"
          labels={{ up: `${name} yukarı`, down: `${name} aşağı` }} onUp={() => move(i, -1)} onDown={() => move(i, 1)} />
      </li>)}
    </ol>
  </Card>
}

import { RowTools, TextInput, Button, Card, Badge, toast } from "march/ui"
import { Icon, plus, mapPin, truck } from "march/icons"

// kuryenin teslimat rotası: durakları sırala, çıkar, yenisini ekle; son durak çıkarılamaz, rota kaydedilince bildirim
export function DeliveryRoute() {
  let $stops = ["Moda Cd. 12, Kadıköy", "Bağdat Cd. 210, Suadiye", "Fenerbahçe Parkı girişi"]
  let $next = ""
  const move = (i: number, d: number) => { const n = [...$stops]; [n[i], n[i + d]] = [n[i + d]!, n[i]!]; $stops = n }
  const remove = (i: number) => { $stops = $stops.filter((_, j) => j !== i) }
  const add = () => { if ($next.trim()) { $stops = [...$stops, $next.trim()]; $next = "" } }
  return <Card title="Bugünkü rota" subtitle="Kurye: Ece K.">
    <ol sx={{ flex: "col", gap: 2 }}>
      {$stops.map((stop, i) => <li sx={{ flex: ["row", "between", "center"], gap: 2 }}>
        <span sx={{ flex: ["row", "center"], gap: 1 }}><Icon of={mapPin} /> {i + 1}. {stop}</span>
        <RowTools index={i} count={$stops.length} danger disabled={{ remove: $stops.length <= 1 }}
          labels={{ up: "Önce git", down: "Sonra git", remove: `${stop} durağını çıkar`, group: `${i + 1}. durak` }}
          onUp={() => move(i, -1)} onDown={() => move(i, 1)} onRemove={() => remove(i)} />
      </li>)}
    </ol>
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2, mt: 3 }}>
      <Badge tone="info">{$stops.length} durak</Badge>
      <TextInput bind:value={$next} placeholder="Yeni durak adresi" aria-label="Yeni durak" />
      <Button icon={plus} variant="secondary" on:click={add}>Ekle</Button>
      <Button icon={truck} on:click={() => toast(`Rota kaydedildi: ${$stops.length} durak`)}>Kaydet</Button>
    </div>
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { RowToolsLab } from "./RowToolsLab.tsx"

// RowToolsLab'in testleri: kaydedince Testler sekmesinde çalışır
const tool = (root: Element, label: string) => root.querySelector(`[aria-label="${label}"]`) as HTMLButtonElement
const names = (root: Element | null) => [...(root?.querySelectorAll("button") ?? [])].map((b) => b.getAttribute("aria-label"))

test("uçlarda oklar kapalı; aşağı taşıyınca sıra ve onAction değişir", async () => {
  const s = renderTest(() => <RowToolsLab />)
  expect(tool(s.container, "Elma yukarı").disabled).toBe(true)
  expect(tool(s.container, "Kiraz aşağı").disabled).toBe(true)
  expect(tool(s.container, "Armut yukarı").disabled).toBe(false)
  await s.click(tool(s.container, "Elma aşağı"))
  expect(s.text()).toContain("Sıra: Armut, Elma, Kiraz · Son araç: down")
  expect(tool(s.container, "Elma aşağı").disabled).toBe(false)
  s.dispose()
})

test("silme: tek satır kalınca sil kapanır; grup adı ve danger", async () => {
  const s = renderTest(() => <RowToolsLab />)
  const group = s.container.querySelector('[aria-label="Elma araçları"]')!
  expect(group.getAttribute("role")).toBe("group")
  expect(tool(s.container, "Elma sil").classList.contains("m-icon-btn-danger")).toBe(true)
  await s.click(tool(s.container, "Kiraz sil"))
  await s.click(tool(s.container, "Armut sil"))
  expect(s.text()).toContain("Sıra: Elma · Son araç: remove")
  expect(tool(s.container, "Elma sil").disabled).toBe(true)
  s.dispose()
})

test("actions: kendi sıram, ad metni ve metin ikon", () => {
  const s = renderTest(() => <RowToolsLab />)
  expect(names(s.container.querySelector(".lab-order"))).toEqual(["Sil", "Yukarı"])
  expect(names(s.container.querySelector(".lab-move"))).toEqual(["Taşı yukarı", "Taşı aşağı"])
  expect(tool(s.container, "Metinle kaldır").textContent).toContain("Kaldır")
  expect(s.container.querySelectorAll('[aria-label^="Boyut"]').length).toBe(4)
  s.dispose()
})

test("disabled: Kilitle bütün araçları kapatır, Kilidi aç geri açar", async () => {
  const s = renderTest(() => <RowToolsLab />)
  expect([...s.container.querySelectorAll(".lab-off button")].every((b) => (b as HTMLButtonElement).disabled)).toBe(true)
  const lock = [...s.container.querySelectorAll("button")].find((b) => b.textContent?.trim() === "Kilitle")!
  await s.click(lock)
  expect([...s.container.querySelectorAll(".lab-row button")].every((b) => (b as HTMLButtonElement).disabled)).toBe(true)
  await s.click(lock)
  expect(tool(s.container, "Armut yukarı").disabled).toBe(false)
  s.dispose()
})
